import './../styles/article.css'
import logo from '../assets/PlancheJaune500.png'


function Article() {
    const prix = 10;
    return (
        <div className="card">
            <div className="card-img">
               <img src={logo}/> 
            </div>
            
            <p>{prix}€</p>
            <p>Mon Article</p>
        </div>
    
    )
}
export default Article;
